const SAMPLE_MALE_HOLY_NAMES = ['Giuse', 'Phêrô', 'Phaolô', 'Gioan', 'Đaminh', 'Antôn', 'Micae', 'Phanxicô', 'Inhaxiô', 'Augustinô'];
